def discounted_return(rewards, gamma):
    value = 0.0
    for reward in reversed(rewards):
        value = reward + gamma * value
    return value


print(discounted_return([1, 2, 3], 0.5))

def td_update(value, reward, next_value, gamma, alpha, terminal):
    continuation = 0.0 if terminal else next_value
    target = reward + gamma * continuation
    return value + alpha * (target - value)


print(td_update(2, 1, 4, 0.9, 0.5, False))
